function sharedPrefs(){
  let p=null;
  try{p=JSON.parse(localStorage.getItem(SHARED_PREFS_KEY)||"null")}catch(_){}
  if(p&&typeof p==="object")return Object.assign(defaultPreferences(),p);
  const seed=Object.assign(defaultPreferences(),activeUser&&state&&state.preferences?state.preferences:{});
  if(activeUser&&state)localStorage.setItem(SHARED_PREFS_KEY,JSON.stringify(seed));
  return seed;
}
function saveSharedPrefs(p){
  const next=Object.assign(defaultPreferences(),p||{});
  localStorage.setItem(SHARED_PREFS_KEY,JSON.stringify(next));
  if(activeUser){
    const keys=["d-study-state::"+activeUser.id,"d-study-tu101-state::"+activeUser.id];
    keys.forEach(function(k){
      try{const x=JSON.parse(localStorage.getItem(k)||"null");if(x&&typeof x==="object"){x.preferences=clone(next);localStorage.setItem(k,JSON.stringify(x))}}catch(_){}
    });
  }
  if(state)state.preferences=clone(next);
  return next;
}
function applyPrefsEverywhere(){
  const p=sharedPrefs();
  if(state)state.preferences=clone(p);
  if(state)coreApplyPreferences();
  else{
    document.body.dataset.accent=p.accent||"navy";
    const dark=p.appearance==="dark"||(p.appearance==="system"&&window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches);
    document.body.classList.toggle("dark",dark);
    const ui=p.uiTheme||"midnight";
    document.body.classList.toggle("neo-ui",ui==="neo");
    document.body.classList.toggle("midnight-ui",ui==="midnight");
    document.body.dataset.uiTheme=ui;
    document.body.classList.toggle("large-text",p.textSize==="large");
    document.body.classList.toggle("flat-cards",p.cardStyle==="flat");
    applyFontKey(p.font||"inter");
  }
  syncSharedSettingControls();
}
function setSharedPref(key,value){
  const p=sharedPrefs();p[key]=value;saveSharedPrefs(p);applyPrefsEverywhere();
}
applyPreferences=function(){applyPrefsEverywhere()};
updatePreference=function(key,value){setSharedPref(key,value);if(state)corePersist()};
applyPublicDefaultTheme=function(){applyPrefsEverywhere()};
saveFont=function(){
  const key=selectedFont();fontPreviewActive=false;setSharedPref("font",key);
  const s=document.getElementById("fontStatus");if(s)s.textContent="Font saved everywhere.";
};
cancelFontPreview=function(){
  fontPreviewActive=false;const p=sharedPrefs();applyFontKey(p.font||"inter");
  const f=document.getElementById("fontSelect");if(f)f.value=p.font||"inter";
  const s=document.getElementById("fontStatus");if(s)s.textContent="Preview cancelled.";
};

function tu101FreshState(){
  const p={};for(let i=1;i<=6;i++)p["Lecture "+i]={current:0,total:0};
  return{subjectId:"tu101",topics:TU101_TOPICS.map(function(t){return{lecture:t.lecture,topic:t.topic,status:"Not Started"}}),pages:p,notes:{},noteMedia:{},accuracy:{},lastReview:{},quizHistory:[],quizTopicStats:{},quizNotes:{sections:{},questions:{}},preferences:clone(sharedPrefs())};
}
function normalizeTu101(x){
  const s=tu101FreshState();
  if(!x||typeof x!=="object")return s;
  if(Array.isArray(x.topics)){
    const byKey=new Map(x.topics.map(function(t){return[(t.lecture||"")+"||"+(t.topic||""),t]}));
    s.topics=s.topics.map(function(t){return Object.assign({},t,byKey.get(t.lecture+"||"+t.topic)||{})});
  }else if(x.status&&typeof x.status==="object"){
    s.topics=s.topics.map(function(t){const id="l"+t.lecture.replace(/\D/g,"");return Object.assign({},t,{status:x.status[id]||"Not Started"})});
  }
  s.pages=Object.assign(s.pages,x.pages||{});
  s.notes=Object.assign({},x.notes||{});
  if(x.status&&x.notes){
    Object.keys(x.notes).forEach(function(k){
      if(/^l\d+$/.test(k)){
        const lecture="Lecture "+k.slice(1),idx=s.topics.findIndex(function(t){return t.lecture===lecture});
        if(idx>=0&&!s.notes[idx])s.notes[idx]=x.notes[k];
      }
    });
  }
  s.noteMedia=(x.noteMedia&&typeof x.noteMedia==="object")?x.noteMedia:{};
  s.accuracy=(x.accuracy&&typeof x.accuracy==="object")?x.accuracy:{};
  s.lastReview=(x.lastReview&&typeof x.lastReview==="object")?x.lastReview:{};
  s.quizHistory=Array.isArray(x.quizHistory)?x.quizHistory:[];
  s.quizTopicStats=(x.quizTopicStats&&typeof x.quizTopicStats==="object")?x.quizTopicStats:{};
  s.quizNotes=(x.quizNotes&&typeof x.quizNotes==="object")?x.quizNotes:{sections:{},questions:{}};
  s.quizNotes.sections=s.quizNotes.sections||{};s.quizNotes.questions=s.quizNotes.questions||{};
  s.preferences=clone(sharedPrefs());
  s.subjectId="tu101";
  return s;
}
normalizeState=function(x){
  if(x&&(x.subjectId==="tu101"||x.group===TU101_GROUP||x.status&&x.version==="1.0"))return normalizeTu101(x);
  return coreNormalizeState(x);
};
stateKey=function(){return activeUser?(activeSubject==="tu101"?"d-study-tu101-state::"+activeUser.id:"d-study-state::"+activeUser.id):"d-study-state::anonymous"};
draftKey=function(mode=quizMode,part=quizPart){return activeUser?(activeSubject==="tu101"?"d-study-tu101-draft::"+activeUser.id+"::"+part+"::"+mode:"d-study-draft::"+activeUser.id+"::"+part+"::"+mode):""};
oldDraftKey=function(mode=quizMode){return activeUser?(activeSubject==="tu101"?"d-study-tu101-draft::"+activeUser.id+"::"+mode:"d-study-draft::"+activeUser.id+"::"+mode):""};
loadState=function(){
  if(activeSubject==="tu101"){
    try{state=normalizeTu101(JSON.parse(localStorage.getItem(stateKey())||"null"))}catch(_){state=tu101FreshState()}
  }else coreLoadState();
  state.preferences=clone(sharedPrefs());
};
function tu101RawKey(){return activeUser?"d-study-tu101-state::"+activeUser.id:""}
function ec214RawKey(){return activeUser?"d-study-state::"+activeUser.id:""}
function recoveryRawKey(){return activeUser?"d-study-recovery::"+activeUser.id+"::ec214":""}
function isTu101StateObject(x){return !!(x&&typeof x==="object"&&(x.subjectId==="tu101"||x.group===TU101_GROUP||(x.version==="1.0"&&x.status&&typeof x.status==="object")))}
function snapshotEc214State(){
  if(!activeUser)return;
  try{
    const raw=localStorage.getItem(ec214RawKey());if(!raw)return;
    const x=JSON.parse(raw);if(isTu101StateObject(x))return;
    localStorage.setItem(recoveryRawKey(),raw);
    localStorage.setItem(recoveryRawKey()+"::meta",JSON.stringify({savedAt:new Date().toISOString(),reason:"subject-switch safeguard"}));
  }catch(_){}
}
persist=function(){
  if(!activeUser||!state)return;
  state.preferences=clone(sharedPrefs());
  if(activeSubject==="tu101"||isTu101StateObject(state)){
    localStorage.setItem(tu101RawKey(),JSON.stringify(state));
    return;
  }
  corePersist();
};
resetData=function(){
  if(activeSubject!=="tu101")return coreResetData();
  if(confirm("Reset all TU101 tracker, notes, quiz history, and drafts for "+activeUser.username+" to 0%?")){
    state=tu101FreshState();persist();
    Object.keys(localStorage).filter(function(k){return k.startsWith("d-study-tu101-draft::"+activeUser.id+"::")}).forEach(function(k){localStorage.removeItem(k)});
    renderTracker();renderNotesHub();renderHistory();renderQuiz();
  }
};

function rebuildLectureFilter(){
  const lf=document.getElementById("lectureFilter");if(!lf||!state)return;
  const current="all";lf.innerHTML='<option value="all">All lectures</option>';
  [...new Set(state.topics.map(function(x){return x.lecture}))].forEach(function(l){const o=document.createElement("option");o.value=l;o.textContent=l;lf.appendChild(o)});
  lf.value=current;
}
function subjectPath(tab){return activeSubject==="tu101"?APP_BASE+"/tu101/"+tab+"/":APP_BASE+"/"+tab+"/"}
function updateNavLinks(){
  document.querySelectorAll("nav.tabs a[data-tab]").forEach(function(a){
    const tab=a.dataset.tab;
    const slug=tab==="tracker"?"progress":tab;
    a.href=subjectPath(slug);
  });
}
function updateBackupLabels(){
  const exportBtn=document.getElementById("exportBtn"),importLabel=document.querySelector('label[for="importFile"],#importLabel');
  const isTu=activeSubject==="tu101";
  if(exportBtn)exportBtn.textContent=isTu?"Export TU101 backup":"Export EC214 backup";
  const importBtn=document.getElementById("importBtn");if(importBtn)importBtn.textContent=isTu?"Import TU101 backup":"Import EC214 backup";
}
function updateChrome(){
  const isTu=activeSubject==="tu101";
  document.body.classList.toggle("subject-tu101",isTu);
  const title=document.querySelector("#appShell header h1");if(title)title.textContent="D Study App • "+(isTu?"TU101":"EC214");
  const sub=document.querySelector("#appShell header .sub");if(sub)sub.textContent="Review first → Master later • autosave + confidence tracking";
  const eyebrow=document.querySelector("#tracker .dashboard-main .eyebrow");if(eyebrow)eyebrow.textContent=(isTu?"TU101":"EC214")+" Study Dashboard";
  const p=document.querySelector("#tracker .dashboard-main p");
  if(p)p.textContent=isTu?"Use Summary for source-grounded review, keep lecture progress and notes here, and use Quiz when the TU101 question bank is added.":"Use Summary for fast recall, Reviewing for your first practice pass, and Mastering only after the concepts feel stable.";
  const qa=document.querySelectorAll("#tracker .quick-actions a");
  if(qa[0]){qa[0].href=isTu?APP_BASE+"/tu101/summary/":APP_BASE+"/sum-43-70/";qa[0].textContent="Continue Summary"}
  if(qa[1]){qa[1].href=isTu?APP_BASE+"/tu101/quiz/":APP_BASE+"/quiz1-42/";qa[1].textContent=isTu?"Open Midterm Quiz":"Open Review Quiz"}
  if(qa[2])qa[2].href=isTu?APP_BASE+"/tu101/notes/":APP_BASE+"/notes/";
  updateNavLinks();
  const footer=document.getElementById("appVersionLabel");if(footer)footer.textContent="D Study App v13.9";
}
function renderTu101Summary(){
  let layer=document.getElementById("tu101SummaryLayer");if(!layer){layer=document.createElement("div");layer.id="tu101SummaryLayer";document.getElementById("summary").appendChild(layer)}
  layer.innerHTML='<div class="panel-intro"><div><div class="eyebrow">Study Notes</div><h2>TU101 Summary Library</h2><p>Midterm scope: Lectures 1–6 • Theme 1 + Theme 2 (Lectures 5–6 only).</p></div></div>'+
  '<div class="summary-search-card tu101-summary-search"><div class="summary-search-head"><div><div class="lecture-title">🔎 Search all TU101 summary context</div><div class="small" id="tu101SearchMeta">Searches Lectures 1–6 + Understand it</div></div><div class="summary-search-input-row"><input id="tu101SummarySearch" type="search" placeholder="Search globalization, hedging, political families, religion…"><button type="button" class="secondary" id="tu101SummaryClear">Clear</button></div></div><div class="summary-search-results" id="tu101SummaryResults"></div></div>'+
  '<div class="summary-library"><div class="lecture-title">📝 TU101 Midterm Summary Library</div><div class="small">Same study-card workflow as EC214; TU101 academic content is separate.</div><div class="tu101-scope-banner"><b>Official Midterm:</b> 80 multiple-choice items • 40% • Lectures 1–6. Climate Change / Human Security remains archived separately because the official course outline labels it Lecture 7.</div></div>'+
  TU101_SUMMARIES.map(function(x,i){return '<article class="slide-card tu101-summary-card" id="tu101-summary-'+(i+1)+'"><div class="slide-no">'+esc(x.lecture)+' • '+esc(x.theme)+'</div><h2>'+esc(x.title)+'</h2><ul>'+x.points.map(function(p){return'<li>'+esc(p)+'</li>'}).join("")+'</ul><div class="summary-deep-dive"><button type="button" class="deep-dive-toggle" aria-expanded="false"><span class="deep-dive-icon">💡</span><span><b>Understand it</b><small>Plain-language connection</small></span><span class="deep-dive-cue">Expand ▾</span></button><div class="deep-dive-expanded" hidden><div class="deep-dive-body"><p>'+esc(x.understand)+'</p></div></div></div></article>'}).join("");
  layer.querySelectorAll(".deep-dive-toggle").forEach(function(b){b.onclick=function(){const box=b.nextElementSibling,on=box.hidden;box.hidden=!on;b.setAttribute("aria-expanded",String(on));const cue=b.querySelector(".deep-dive-cue");if(cue)cue.textContent=on?"Collapse ▴":"Expand ▾"}});
  const input=layer.querySelector("#tu101SummarySearch"),results=layer.querySelector("#tu101SummaryResults"),meta=layer.querySelector("#tu101SearchMeta");
  function clearMarks(){layer.querySelectorAll("mark.tu101-search-mark").forEach(function(m){m.replaceWith(document.createTextNode(m.textContent))})}
  function highlight(root,q){clearMarks();const term=q.trim();if(!term)return null;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(w.nextNode())nodes.push(w.currentNode);for(const n of nodes){const p=n.parentElement;if(!p||p.closest("script,style,input,textarea,mark"))continue;const at=n.nodeValue.toLowerCase().indexOf(term.toLowerCase());if(at>=0){const f=document.createDocumentFragment();f.append(n.nodeValue.slice(0,at));const m=document.createElement("mark");m.className="tu101-search-mark";m.textContent=n.nodeValue.slice(at,at+term.length);f.append(m);f.append(n.nodeValue.slice(at+term.length));n.parentNode.replaceChild(f,n);return m}}return null}
  function run(){const q=(input.value||"").trim().toLowerCase();clearMarks();if(!q){results.innerHTML='<div class="summary-search-empty">Search any word or phrase across TU101 Lectures 1–6.</div>';meta.textContent="Searches Lectures 1–6 + Understand it";return}const terms=q.split(/\s+/).filter(Boolean);const hits=TU101_SUMMARIES.map(function(x,i){const main=(x.title+" "+x.points.join(" ")).toLowerCase(),deep=x.understand.toLowerCase(),all=main+" "+deep;return{data:x,i,main,deep,all}}).filter(function(x){return terms.every(function(t){return x.all.includes(t)})});meta.textContent=hits.length+" result"+(hits.length===1?"":"s");results.innerHTML=hits.length?hits.map(function(h){const inDeep=!terms.every(function(t){return h.main.includes(t)})&&terms.every(function(t){return h.deep.includes(t)});return '<button class="summary-search-result" type="button" data-tu-hit="'+h.i+'" data-tu-deep="'+(inDeep?"1":"0")+'"><span class="summary-search-source">'+esc(h.data.lecture)+(inDeep?" • Understand it":"")+'</span><b>'+esc(h.data.title)+'</b><span>'+esc((inDeep?h.data.understand:h.data.points.join(" ")).slice(0,220))+'…</span></button>'}).join(""):'<div class="summary-search-empty">No TU101 summary context matched “'+esc(input.value)+'”.</div>';results.querySelectorAll("[data-tu-hit]").forEach(function(b){b.onclick=function(){const card=layer.querySelector("#tu101-summary-"+(Number(b.dataset.tuHit)+1));if(b.dataset.tuDeep==="1"){const ex=card.querySelector(".deep-dive-expanded");if(ex&&ex.hidden)card.querySelector(".deep-dive-toggle").click()}setTimeout(function(){const mark=highlight(b.dataset.tuDeep==="1"?card.querySelector(".deep-dive-expanded"):card,input.value);(mark||card).scrollIntoView({behavior:"smooth",block:"center"})},40)}})}
  input.oninput=run;layer.querySelector("#tu101SummaryClear").onclick=function(){input.value="";run()};run();
}
function renderTu101QuizLayer(){
  let layer=document.getElementById("tu101QuizLayer");if(!layer){layer=document.createElement("div");layer.id="tu101QuizLayer";document.getElementById("quiz").appendChild(layer)}
  layer.innerHTML='<div class="panel-intro"><div><div class="eyebrow">Practice</div><h2>TU101 Quiz Library</h2><p>The TU101 quiz bank has not been created yet. The quiz workspace will use the same Reviewing/Mastering, notes, confidence flags, drafts, history, and mistake-log behavior as EC214 once questions are added.</p></div></div><div class="card quiz-shell"><div class="mode-switch"><button class="mode-btn active" type="button" disabled><b>Reviewing</b><span class="small">Question bank pending</span></button><button class="mode-btn" type="button" disabled><b>Mastering</b><span class="small">Question bank pending</span></button></div><div class="tu101-quiz-empty"><div class="eyebrow">Midterm Exam</div><h3>80 multiple-choice items • 40%</h3><p>Official scope: Lectures 1–6. No quiz questions have been generated in this update, as requested.</p><div class="tu101-tags"><span>Theme 1 • Lectures 1–4</span><span>Theme 2 • Lectures 5–6</span><span>'+esc(TU101_GROUP)+'</span></div></div></div>';
}
renderQuiz=function(){if(activeSubject==="tu101"){renderTu101QuizLayer();return}return coreRenderQuiz()};
renderQuizSetButtons=function(){if(activeSubject==="tu101")return;return coreRenderQuizSetButtons()};
renderQuizPartButtons=function(){if(activeSubject==="tu101")return;return coreRenderQuizPartButtons()};
renderQuizLibraryProgress=function(){if(activeSubject==="tu101")return;return coreRenderQuizLibraryProgress()};

function configureSubjectPanels(){
  ensureFlashcardWorkspace();updateChrome();updateBackupLabels();ensureLocalRecoveryPanel();
  if(activeSubject==="tu101"){renderTu101Summary();renderTu101QuizLayer()}
  rebuildLectureFilter();
  renderTracker();renderNotesHub();renderHistory();renderFlashcards();applyPrefsEverywhere();
}
function enterTu101(remember){
  if(!activeUser||!hasSubjectAccess(activeUser,"tu101"))return;
  if(state&&!isTu101StateObject(state)){snapshotEc214State();persist()}
  else if(state)persist();
  activeSubject="tu101";if(remember!==false)rememberSubjectSession("tu101");
  loadState();
  document.getElementById("subjectScreen").style.display="none";
  document.getElementById("appShell").style.display="block";
  const old=document.getElementById("tu101Shell");if(old)old.remove();
  const chip=document.getElementById("userChip");if(chip)chip.textContent="👤 "+activeUser.username;
  configureSubjectPanels();
  applyPathRoute();
}
enterSubject=function(subjectId,remember=true){
  if(subjectId==="tu101")return enterTu101(remember);
  if(subjectId==="ec214"){
    if(state)persist();
    activeSubject="ec214";loadState();configureSubjectPanels();return coreEnterSubject("ec214",remember);
  }
};
backToSubjects=function(){
  if(activeSubject==="tu101"){
    persist();activeSubject=null;clearSubjectSession();document.getElementById("appShell").style.display="none";renderSubjectHub();return;
  }
  return coreBackToSubjects();
};
const bts=document.getElementById("backToSubjectsBtn");if(bts)bts.onclick=backToSubjects;

function ensureTu101Card(){
  const grid=document.querySelector("#subjectScreen .subject-grid");if(!grid||document.getElementById("subjectTu101Card"))return;
  const card=document.createElement("article");card.className="subject-card live tu101-card";card.id="subjectTu101Card";card.dataset.subject="tu101";
  card.innerHTML='<span class="subject-state" id="subjectTu101State">Locked</span><strong>TU101</strong><span>Thailand, ASEAN and the World</span><small>'+esc(TU101_GROUP)+' • same D Study App workspace</small><div class="subject-card-actions"><button id="subjectTu101OpenBtn" type="button">Unlock TU101</button><button id="subjectTu101PreviewBtn" class="secondary" type="button">Preview</button></div>';
  grid.insertBefore(card,grid.querySelector(".subject-card.coming")||null);
  document.getElementById("subjectTu101OpenBtn").onclick=function(){chooseSubject("tu101")};
  document.getElementById("subjectTu101PreviewBtn").onclick=function(){openSubjectPreview("tu101")};
}
renderSubjectHub=function(){
  coreRenderSubjectHub();ensureTu101Card();
  if(!activeUser)return;
  const yes=hasSubjectAccess(activeUser,"tu101"),card=document.getElementById("subjectTu101Card"),st=document.getElementById("subjectTu101State"),btn=document.getElementById("subjectTu101OpenBtn");
  card&&card.classList.toggle("unlocked",yes);if(st)st.textContent=yes?"Unlocked":"Locked";if(btn){btn.textContent=yes?"Open TU101":"Unlock TU101";btn.classList.toggle("secondary",yes)}
  applyPrefsEverywhere();
};
function openUnlock(subjectId){
  unlockTarget=subjectId;const panel=document.getElementById("subjectUnlockPanel"),preview=document.getElementById("subjectPreviewPanel"),input=document.getElementById("subjectPasswordInput"),status=document.getElementById("subjectUnlockStatus"),h=panel&&panel.querySelector("h2"),p=panel&&panel.querySelector("p.small");
  if(preview)preview.hidden=true;if(status)status.textContent="";if(panel)panel.hidden=false;
  if(subjectId==="tu101"){if(h)h.textContent="Enter the TU101 subject token";if(p)p.textContent="TU101 uses a separate token but the same D Study App functions and linked appearance settings.";if(input)input.placeholder="TU101 token"}
  else{if(h)h.textContent="Enter the EC214 subject password";if(p)p.textContent="Enter it once for this local account. After successful redemption, the account keeps EC214 access.";if(input)input.placeholder="Subject password"}
  setTimeout(function(){input&&input.focus()},0);
}
if(typeof DEPLOYED_SUBJECT_HASHES!=="undefined")DEPLOYED_SUBJECT_HASHES.tu101=TU101_TOKEN_HASH;
chooseSubject=function(subjectId){
  if(subjectId==="tu101"){if(hasSubjectAccess(activeUser,"tu101"))enterSubject("tu101");else openUnlock("tu101");return}
  unlockTarget="ec214";return coreChooseSubject(subjectId);
};
unlockSelectedSubject=async function(){
  const subjectId=unlockTarget||"ec214",name=subjectId==="tu101"?"TU101":"EC214",input=document.getElementById("subjectPasswordInput"),status=document.getElementById("subjectUnlockStatus"),value=input?input.value:"";
  if(!value){if(status)status.textContent="Enter the "+name+" subject "+(subjectId==="tu101"?"token.":"password.");return}
  if(await sha256Text(value)!==subjectPasswordHash(subjectId)){if(status)status.textContent="Incorrect "+name+" subject "+(subjectId==="tu101"?"token.":"password.");return}
  grantSubjectAccess(subjectId);if(input)input.value="";if(status)status.textContent="";const p=document.getElementById("subjectUnlockPanel");if(p)p.hidden=true;renderSubjectHub();enterSubject(subjectId);
};
const ub=document.getElementById("subjectUnlockBtn");if(ub)ub.onclick=unlockSelectedSubject;

applyPathRoute=function(){
  const p=location.pathname.replace(/\/+$/,"");
  if(activeSubject!=="tu101"){
    if(p.endsWith("/flashcards")){ensureFlashcardWorkspace();switchTab("flashcards");renderFlashcards();return}
    return coreApplyPathRoute();
  }
  if(p.endsWith("/flashcards")){ensureFlashcardWorkspace();switchTab("flashcards");renderFlashcards();return}
  if(p.endsWith("/summary")){switchTab("summary");renderTu101Summary();return}
  if(p.endsWith("/quiz")){switchTab("quiz");renderTu101QuizLayer();return}
  if(p.endsWith("/notes")){switchTab("notes");renderNotesHub();return}
  if(p.endsWith("/history")){switchTab("history");renderHistory();return}
  if(p.endsWith("/prompt")){switchTab("prompt");return}
  if(p.endsWith("/settings")){switchTab("settings");applyPrefsEverywhere();return}
  switchTab("tracker");renderTracker();
};

